INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
  ('b0000000-0000-0000-0006-000000000000', 'JavaScript란 무엇이며 주로 어디에 사용되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000001', '자바스크립트의 주요 특징(동적 타입, 인터프리터 언어 등)은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000002', 'JavaScript의 자료형(Data Type)에는 어떤 것들이 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000003', 'var, let, const의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000004', '호이스팅(Hoisting)이란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000005', '클로저(Closure)란 무엇이고 어떻게 활용될 수 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000006', '이벤트 버블링(Event Bubbling)과 캡처링(Capturing)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000007', 'Arrow 함수와 일반 function의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000008', '==와 ===의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000009', 'NaN, undefined, null의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000a', 'JavaScript의 비동기 처리 방법에는 무엇이 있나요? (콜백, 프로미스, async/await)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000b', 'Promise의 상태(state)와 결과(value)는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000c', 'async/await를 사용하면 어떤 장점이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000d', 'JavaScript에서 호이스팅이 일어나는 대상은 무엇인가요? (변수, 함수 등)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000e', '이벤트 루프(Event Loop)와 태스크 큐(Task Queue)는 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-00000000000f', '브라우저의 렌더링 엔진과 JavaScript 엔진의 차이는?', 'HARD', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000010', 'Strict 모드(''use strict'')는 무엇이고 사용하는 이유는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000011', 'ES6(ES2015)의 주요 추가 기능들을 몇 가지 설명해 주세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000012', '디바운스(Debounce)와 스로틀(Throttle)의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006'),
  ('b0000000-0000-0000-0006-000000000013', '모듈 번들러(예: Webpack)는 어떤 역할을 하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000006');
